import Ajv from 'ajv';
import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry rejection paths', () => {
  // spec: specs/hal-engine-tool-input-validation/spec.md#4
  it('names a slash-bearing property without exposing its value', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'lookup',
        description: 'Look up a record',
        inputSchema: {type: 'object', properties: {'personal/data': {type: 'string'}}},
      },
      async () => 'unreachable'
    );

    const response = await registry.execute('lookup', {'personal/data': 123456789});

    expect({
      path: response.result.includes('personal/data'),
      type: response.result.includes('string'),
      leaked: response.result.includes('123456789'),
    }).toEqual({path: true, type: true, leaked: false});
  });

  // spec: specs/hal-engine-tool-input-validation/spec.md#5
  it('names an explicitly forbidden extra property without exposing its value', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'lookup',
        description: 'Look up a record',
        inputSchema: {type: 'object', additionalProperties: false},
      },
      async () => 'unreachable'
    );

    const personalIdKey = 'personal_id';
    const response = await registry.execute('lookup', {[personalIdKey]: 'secret-123'});

    expect({
      path: response.result.includes('personal_id'),
      constraint: response.result.includes('additionalProperties'),
      leaked: response.result.includes('secret-123'),
    }).toEqual({path: true, constraint: true, leaked: false});
  });

  // spec: specs/hal-engine-tool-input-validation/spec.md#4
  it('names an array element field with its index and expected type', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'forecast',
        description: 'Get forecasts',
        inputSchema: {
          type: 'object',
          properties: {
            forecasts: {type: 'array', items: {type: 'object', properties: {location: {type: 'string'}}}},
          },
        },
      },
      async () => 'unreachable'
    );

    const response = await registry.execute('forecast', {forecasts: [{location: 12345}]});

    expect(response.result).toBe('forecasts[0].location must be string');
  });
});

describe('ToolRegistry schema compilation', () => {
  // spec: specs/hal-engine-tool-input-validation/spec.md#10
  it('keeps the schema compiled at registration when a static definition changes', async () => {
    const registry = new ToolRegistry();
    const definition = {
      name: 'weather',
      description: 'Get weather',
      inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
    };
    const inputs: Array<Record<string, unknown>> = [];
    registry.register(definition, async input => {
      inputs.push(input);
      return 'forecast';
    });
    definition.inputSchema = {type: 'object', properties: {location: {type: 'string'}}, required: ['days']};

    const response = await registry.execute('weather', {location: 'Paris'});

    expect({response, inputs}).toEqual({response: {result: 'forecast'}, inputs: [{location: 'Paris'}]});
  });

  // spec: specs/hal-engine-tool-input-validation/spec.md#9
  it('rejects an invalid static input schema when registering its named tool', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_weather',
          description: 'Get weather',
          inputSchema: {type: 'object', properties: {location: {type: 'not-a-json-schema-type'}}},
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_weather/);
  });
});

describe('ToolRegistry dynamic schema validation', () => {
  // spec: specs/hal-engine-tool-input-validation/spec.md#11
  it('uses each current schema and compiles each schema object once', async () => {
    const registry = new ToolRegistry();
    const locationSchema = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    const forecastSchema = {
      type: 'object',
      properties: {days: {type: 'number'}},
      required: ['days'],
    };
    let schema: Record<string, unknown> = locationSchema;
    const inputs: Array<Record<string, unknown>> = [];
    registry.register(
      () => ({name: 'weather', description: 'Get weather', inputSchema: schema}),
      async input => {
        inputs.push(input);
        return 'forecast';
      }
    );
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    try {
      const missingLocation = await registry.execute('weather', {});
      const location = await registry.execute('weather', {location: 'Paris'});
      schema = forecastSchema;
      const missingDays = await registry.execute('weather', {location: 'Paris'});
      const days = await registry.execute('weather', {days: 2});
      const calls = compile.mock.calls;

      expect({
        missingLocation: missingLocation.result.includes('location'),
        location: location.result,
        missingDays: missingDays.result.includes('days'),
        days: days.result,
        inputs,
        compileCalls: calls.length,
      }).toEqual({
        missingLocation: true,
        location: 'forecast',
        missingDays: true,
        days: 'forecast',
        inputs: [{location: 'Paris'}, {days: 2}],
        compileCalls: 2,
      });
    } finally {
      compile.mockRestore();
    }
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46)).
- A failing field path uses the declared property name even when that name contains a slash, renders array indexes in brackets, and the rejection does not include the supplied value ([validated by: names a slash-bearing property without exposing its value](../../src/orchestration/tools/registry.test.ts#L7); [validated by: names an array element field with its index and expected type](../../src/orchestration/tools/registry.test.ts#L50)).
- When a schema explicitly sets `additionalProperties: false`, a rejected extra property is named along with the `additionalProperties` constraint, without exposing its value ([validated by: names an explicitly forbidden extra property without exposing its value](../../src/orchestration/tools/registry.test.ts#L28)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults.
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94)).
- Registering a static tool with an invalid schema throws an error naming that tool ([validated by: rejects an invalid static input schema when registering its named tool](../../src/orchestration/tools/registry.test.ts#L94)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema` ([validated by: keeps the schema compiled at registration when a static definition changes](../../src/orchestration/tools/registry.test.ts#L74)).
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules ([validated by: uses each current schema and compiles each schema object once](../../src/orchestration/tools/registry.test.ts#L112)).

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).
